// ----- inlined: src/lib/dates.js -----
/**
 * dates.js — timezone-aware business-day arithmetic.
 *
 * Every scheduling decision in this system is made in ONE configured IANA
 * timezone (CAMPAIGN_TIMEZONE). We never compare raw UTC timestamps, because
 * "3 business days ago" is a calendar question, not a duration question:
 * a lead contacted Friday 23:50 UTC and one contacted Friday 00:10 UTC are
 * both "contacted on Friday" and must both become due on Wednesday.
 */

var DATES_MAX_ITER = 4000; // hard stop so a bad date can never spin forever

/** Format a Date as 'YYYY-MM-DD' as observed in `timeZone`. */
function zonedYMD(date, timeZone) {
  var d = toDate(date);
  if (!d) return null;
  // en-CA renders as YYYY-MM-DD, which is exactly the shape we want.
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: timeZone || 'UTC',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(d);
}

/** Hour (0-23) as observed in `timeZone`. */
function zonedHour(date, timeZone) {
  var d = toDate(date);
  if (!d) return null;
  var parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: timeZone || 'UTC',
    hour: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(d);
  for (var i = 0; i < parts.length; i++) {
    if (parts[i].type === 'hour') return parseInt(parts[i].value, 10);
  }
  return null;
}

/** Coerce ISO string / Date / epoch ms to a valid Date, or null. */
function toDate(value) {
  if (value === null || value === undefined || value === '') return null;
  var d = value instanceof Date ? value : new Date(value);
  return isNaN(d.getTime()) ? null : d;
}

/** 'YYYY-MM-DD' -> Date at UTC midnight (a pure calendar-day handle). */
function ymdToUTC(ymd) {
  if (typeof ymd !== 'string') return null;
  var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ymd.trim());
  if (!m) return null;
  var d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return isNaN(d.getTime()) ? null : d;
}

/** Date at UTC midnight -> 'YYYY-MM-DD'. */
function utcToYMD(date) {
  return date.toISOString().slice(0, 10);
}

/** Shift a 'YYYY-MM-DD' by n calendar days. */
function shiftYMD(ymd, days) {
  var d = ymdToUTC(ymd);
  if (!d) return null;
  d.setUTCDate(d.getUTCDate() + days);
  return utcToYMD(d);
}

/** Normalize a holiday list into a Set of 'YYYY-MM-DD'. */
function holidaySet(holidays) {
  var set = new Set();
  if (!holidays) return set;
  var list = Array.isArray(holidays)
    ? holidays
    : String(holidays).split(',');
  for (var i = 0; i < list.length; i++) {
    var v = String(list[i]).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(v)) set.add(v);
  }
  return set;
}

/** Is this calendar day a business day (Mon-Fri, not a holiday)? */
function isBusinessDayYMD(ymd, holidays) {
  var d = ymdToUTC(ymd);
  if (!d) return false;
  var dow = d.getUTCDay(); // 0 Sun .. 6 Sat
  if (dow === 0 || dow === 6) return false;
  return !holidaySet(holidays).has(ymd);
}

/** Is `date`, as observed in `timeZone`, on a business day? */
function isBusinessDay(date, timeZone, holidays) {
  var ymd = zonedYMD(date, timeZone);
  return ymd ? isBusinessDayYMD(ymd, holidays) : false;
}

/**
 * Signed count of business days strictly after `fromYMD` up to and including
 * `toYMD`. Same day -> 0. Fri -> Mon -> 1. Fri -> Wed -> 3.
 */
function businessDaysBetweenYMD(fromYMD, toYMD, holidays) {
  var from = ymdToUTC(fromYMD);
  var to = ymdToUTC(toYMD);
  if (!from || !to) return null;
  var sign = 1;
  if (to.getTime() < from.getTime()) {
    sign = -1;
    var swap = from; from = to; to = swap;
  }
  var hol = holidaySet(holidays);
  var count = 0;
  var cursor = new Date(from.getTime());
  var guard = 0;
  while (cursor.getTime() < to.getTime() && guard++ < DATES_MAX_ITER) {
    cursor.setUTCDate(cursor.getUTCDate() + 1);
    var ymd = utcToYMD(cursor);
    var dow = cursor.getUTCDay();
    if (dow !== 0 && dow !== 6 && !hol.has(ymd)) count++;
  }
  return sign * count;
}

/**
 * Business days elapsed since `fromIso` as of `nowIso`, both interpreted in
 * `timeZone`. This is the value the follow-up gates compare against.
 * Returns null when `fromIso` is missing/unparseable — callers MUST treat
 * null as "not due" rather than "due", so a corrupt date can never trigger
 * an unwanted send.
 */
function businessDaysSince(fromIso, nowIso, timeZone, holidays) {
  var fromYMD = zonedYMD(fromIso, timeZone);
  var nowYMD = zonedYMD(nowIso || new Date(), timeZone);
  if (!fromYMD || !nowYMD) return null;
  return businessDaysBetweenYMD(fromYMD, nowYMD, holidays);
}

/** Add n business days to a date, returning 'YYYY-MM-DD'. */
function addBusinessDays(date, n, timeZone, holidays) {
  var ymd = zonedYMD(date, timeZone);
  if (!ymd) return null;
  var remaining = Math.abs(n);
  var step = n < 0 ? -1 : 1;
  var guard = 0;
  while (remaining > 0 && guard++ < DATES_MAX_ITER) {
    ymd = shiftYMD(ymd, step);
    if (isBusinessDayYMD(ymd, holidays)) remaining--;
  }
  return ymd;
}

/** True when the local hour is inside [startHour, endHour). */
function isWithinSendWindow(date, timeZone, startHour, endHour) {
  var h = zonedHour(date, timeZone);
  if (h === null) return false;
  return h >= startHour && h < endHour;
}

/**
 * Seconds of runway left in today's send window. Used to refuse to start a
 * batch we cannot finish before the window closes.
 */
function secondsLeftInWindow(date, timeZone, endHour) {
  var d = toDate(date);
  if (!d) return 0;
  var h = zonedHour(d, timeZone);
  if (h === null) return 0;
  var minutes = Number(
    new Intl.DateTimeFormat('en-GB', {
      timeZone: timeZone || 'UTC', minute: '2-digit'
    }).format(d)
  );
  var elapsed = h * 3600 + minutes * 60;
  var closes = endHour * 3600;
  return Math.max(0, closes - elapsed);
}

/**
 * Deterministic-when-seeded randomized stagger, in seconds.
 * `rng` defaults to Math.random; tests inject a fixed value.
 */
function staggerSeconds(minMinutes, maxMinutes, rng) {
  var lo = Math.max(0, Number(minMinutes) || 0);
  var hi = Math.max(lo, Number(maxMinutes) || lo);
  var r = typeof rng === 'function' ? rng() : Math.random();
  if (!(r >= 0 && r < 1)) r = 0.5;
  return Math.round((lo + (hi - lo) * r) * 60);
}

// ----- node body: src/nodes/w1-01-config.js -----

// n8n Code node — "Init Config" (Run Once for All Items)
//


/** Read an n8n environment variable, if this instance allows it. */
function env(name) {
  try {
    var v = $env[name];
    if (v === undefined || v === null || String(v).trim() === '') return null;
    return String(v).trim();
  } catch (e) {
    // n8n Cloud, or N8N_BLOCK_ENV_ACCESS_IN_NODE=true. Not an error — the
    // SETTINGS block above is the supported path in that case.
    return null;
  }
}

/** SETTINGS wins, then the environment, then the built-in default. */
function setting(name, fallback) {
  var v = SETTINGS[name];
  if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  var e = env(name);
  return e === null ? fallback : e;
}

function settingNum(name, fallback) {
  var raw = setting(name, null);
  // Number(null) is 0, not NaN — without this guard an unset value would read
  // as a cap of 0 and the workflow would refuse to run for everyone on defaults.
  if (raw === null) return fallback;
  var n = Number(raw);
  return isFinite(n) ? n : fallback;
}

function settingBool(name, fallback) {
  var raw = setting(name, null);
  return raw === null ? fallback : /^(1|true|yes|on)$/i.test(raw);
}

var nowIso = new Date().toISOString();

var cfg = {
  runId: 'run_' + nowIso.replace(/[^0-9]/g, '').slice(0, 14) + '_' + Math.random().toString(36).slice(2, 8),
  now: nowIso,

  // --- Airtable -----------------------------------------------------------
  airtableApiBase: 'https://api.airtable.com/v0',
  airtableMetaBase: 'https://api.airtable.com/v0/meta',
  baseId: setting('AIRTABLE_BASE_ID', ''),
  tableName: setting('AIRTABLE_TABLE_NAME', 'Leads'),
  manageOptionalFields: settingBool('MANAGE_OPTIONAL_FIELDS', true),

  // --- Scheduling ---------------------------------------------------------
  timeZone: setting('CAMPAIGN_TIMEZONE', 'America/New_York'),
  holidays: setting('CAMPAIGN_HOLIDAYS', ''),
  dailyCap: settingNum('DAILY_SEND_CAP', 30),
  staggerMinMinutes: settingNum('STAGGER_MIN_MINUTES', 15),
  staggerMaxMinutes: settingNum('STAGGER_MAX_MINUTES', 20),
  sendWindowStartHour: settingNum('SEND_WINDOW_START_HOUR', 8),
  sendWindowEndHour: settingNum('SEND_WINDOW_END_HOUR', 18),

  // --- Verification -------------------------------------------------------
  millionVerifierKey: setting('MILLIONVERIFIER_API_KEY', ''),
  millionVerifierTimeout: settingNum('MILLIONVERIFIER_TIMEOUT_SECONDS', 20),
  allowRisky: settingBool('ALLOW_RISKY', false),
  forceReverify: settingBool('FORCE_REVERIFY', false),

  // --- Sending ------------------------------------------------------------
  emailProvider: setting('EMAIL_PROVIDER', 'postmark').toLowerCase(),
  postmarkEndpoint: 'https://api.postmarkapp.com/email',
  postmarkMessageStream: setting('POSTMARK_MESSAGE_STREAM', 'outbound'),
  postmarkMessageIdDomain: setting('POSTMARK_MESSAGE_ID_DOMAIN', 'mtasv.net'),
  senderName: setting('SENDER_NAME', ''),
  senderEmail: setting('SENDER_EMAIL', ''),
  senderCompany: setting('SENDER_COMPANY', ''),
  senderPostalAddress: setting('SENDER_POSTAL_ADDRESS', ''),
  replyToEmail: setting('REPLY_TO_EMAIL', ''),

  // --- Ops ----------------------------------------------------------------
  slackWebhookUrl: setting('SLACK_WEBHOOK_URL', ''),
  dryRun: settingBool('DRY_RUN', true)
};

cfg.fromHeader = cfg.senderName
  ? '"' + cfg.senderName.replace(/"/g, '') + '" <' + cfg.senderEmail + '>'
  : cfg.senderEmail;

// --- Preflight: refuse to run half-configured rather than half-send. ------
var missing = [];
if (!cfg.baseId) missing.push('AIRTABLE_BASE_ID');
if (!cfg.tableName) missing.push('AIRTABLE_TABLE_NAME');
if (!cfg.senderEmail) missing.push('SENDER_EMAIL');
if (!cfg.senderName) missing.push('SENDER_NAME');
if (!cfg.millionVerifierKey) missing.push('MILLIONVERIFIER_API_KEY');
if (!cfg.senderPostalAddress) missing.push('SENDER_POSTAL_ADDRESS (legally required on commercial email)');

if (cfg.dailyCap < 1 || cfg.dailyCap > 200) missing.push('DAILY_SEND_CAP must be between 1 and 200');
if (cfg.staggerMinMinutes < 0 || cfg.staggerMaxMinutes < cfg.staggerMinMinutes) {
  missing.push('STAGGER_MIN_MINUTES / STAGGER_MAX_MINUTES are inconsistent');
}
if (cfg.sendWindowEndHour <= cfg.sendWindowStartHour) {
  missing.push('SEND_WINDOW_END_HOUR must be later than SEND_WINDOW_START_HOUR');
}
if (missing.length) {
  throw new Error(
    'Setup is incomplete. Open this node ("Init Config"), scroll to the SETTINGS ' +
    'block at the top, and fill in:\n  - ' + missing.join('\n  - ') +
    '\nNothing was sent.'
  );
}

// --- Is today a sending day? ---------------------------------------------
var todayYMD = zonedYMD(cfg.now, cfg.timeZone);
var businessDay = isBusinessDayYMD(todayYMD, cfg.holidays);
var inWindow = isWithinSendWindow(cfg.now, cfg.timeZone, cfg.sendWindowStartHour, cfg.sendWindowEndHour);
var runway = secondsLeftInWindow(cfg.now, cfg.timeZone, cfg.sendWindowEndHour);

// How many sends can actually fit before the window closes, at the WORST
// case stagger? Trimming here is what stops a batch stranding half-sent.
var worstCaseGap = cfg.staggerMaxMinutes * 60;
var fitsInWindow = worstCaseGap > 0 ? Math.floor(runway / worstCaseGap) + 1 : cfg.dailyCap;
var effectiveCap = Math.max(0, Math.min(cfg.dailyCap, fitsInWindow));

var shouldRun = businessDay && inWindow && effectiveCap > 0;

console.log('[' + cfg.runId + '] ' + todayYMD + ' ' + cfg.timeZone +
  ' | cap ' + effectiveCap + '/' + cfg.dailyCap +
  ' | dryRun=' + cfg.dryRun +
  ' | run=' + shouldRun);

return [{
  json: {
    cfg: cfg,
    runDate: todayYMD,
    businessDay: businessDay,
    inSendWindow: inWindow,
    secondsLeftInWindow: runway,
    effectiveCap: effectiveCap,
    shouldRun: shouldRun,
    haltReason: shouldRun
      ? null
      : (!businessDay
          ? 'Not a business day (' + todayYMD + ').'
          : (!inWindow
              ? 'Outside the send window ' + cfg.sendWindowStartHour + ':00-' + cfg.sendWindowEndHour + ':00 ' + cfg.timeZone + '.'
              : 'Not enough time left in the send window for even one staggered send.'))
  }
}];

